public record LateGameDecisionData(int sequence,int dueTimeSeconds,int actualEvaluationTimeSeconds,List<LateGameInitiativeCandidate> initiativeCandidates,TeamSide initiativeSide,boolean initiativeRollExecuted,List<LateGamePlanWeightBreakdown> attackCandidates,LateGameAttackPlan selectedAttackPlan,boolean attackPlanRollExecuted,Lane targetLane,LateGameStructureTarget targetStructure,Set<Position> assignedPositions,List<LateGameDefenseWeightBreakdown> defenseCandidates,LateGameDefenseResponse selectedDefenseResponse,boolean defenseRollExecuted,BaseThreatSnapshot blueBaseThreat,BaseThreatSnapshot redBaseThreat,int attackerAliveCount,int defenderAliveCount,LateGameRespawnSummary defenderRespawnSummary,double siegeFightTriggerChance,boolean siegeFightTriggered,FightGrade fightGrade,TeamSide fightWinner,double structureChance,boolean structureRollExecuted,boolean structureSucceeded,Lane crossMapTargetLane,LateGameStructureTarget crossMapTargetStructure,double crossMapChance,boolean crossMapRollExecuted,boolean crossMapSucceeded,LateGameActionResult result,boolean majorCombatConsumed,boolean attackerStructureActionConsumed,boolean defenderStructureActionConsumed,int nextEvaluationAtSeconds){public LateGameDecisionData{initiativeCandidates=initiativeCandidates==null?List.of():List.copyOf(initiativeCandidates);attackCandidates=attackCandidates==null?List.of():List.copyOf(attackCandidates);assignedPositions=assignedPositions==null||assignedPositions.isEmpty()?Set.of():Set.copyOf(assignedPositions);defenseCandidates=defenseCandidates==null?List.of():List.copyOf(defenseCandidates);}}
